  ms=int(min(120000,(remaining-20)*1000));t=time.monotonic();rec={'phase':name,'user':user,'database':db,'sql_sha256':hashlib.sha256(body.encode()).hexdigest()};result['sql_submissions']+=1
  try:
   r=command(['exec','-i','-e',f'PGOPTIONS=-c statement_timeout={ms} -c transaction_timeout={ms+2000} -c lock_timeout=3000',ID,'psql','-X','-qAt','-v','ON_ERROR_STOP=1','-U',user,'-d',db],body,(ms+7000)/1000)
   rec.update({'status':'PASS' if r.returncode==0 else 'FAIL','exit_code':r.returncode,'stdout':r.stdout[-12000:],'stderr':r.stderr[-4000:]})
  except subprocess.TimeoutExpired:rec.update({'status':'TIMEOUT','note':'Server timeouts bounded; shared container preserved, never stopped. No retry.'})
